def parse_nested_parens(paren_string: str) -> List[int]:
    result = []
    current_depth = 0
    max_depth = 0

    for c in paren_string:
        if c == '(':
            current_depth += 1
            max_depth = max(max_depth, current_depth)
        elif c == ')':
            current_depth -= 1
        elif c == ' ':
            if max_depth > 0:
                result.append(max_depth)
                max_depth = 0

    # Don't forget the last group
    if max_depth > 0:
        result.append(max_depth)

    return result

