def sort_numbers(numbers: str) -> str:
    number_map = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    # Split the input string into individual numberals
    numberals = numbers.split()

    # Convert numberals to their corresponding numeric values, sort them, then convert back
    sorted_numbers = sorted(numberals, key=lambda x: number_map[x])

    # Join the sorted numberals back into a string
    return ' '.join(sorted_numbers)

