def fibfib(n: int) -> int:
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 1

    # Use dynamic programming with three variables to store the last three values
    a, b, c = 0, 0, 1  # fibfib(0), fibfib(1), fibfib(2)

    for i in range(3, n + 1):
