def fruit_distribution(s: str, n: int) -> int:
    # Extract numbers from the string using string parsing
    words = s.split()
    apples = 0
    oranges = 0

    for i, word in enumerate(words):
        if word.isdigit():
            if i > 0 and words[i-1] == "apples":
                apples = int(word)
            elif i > 0 and words[i-1] == "oranges":
                oranges = int(word)

    # Calculate mango fruits
    mangoes = n - apples - oranges
    return mangoes

