initial_code:
def pluck(arr):
    if not arr:
        return []

    min_even_value = float('inf')
    min_index = -1

    for i, num in enumerate(arr):
        if num % 2 == 0 and num < min_even_value:
            min_even_value = num
            min_index = i

    if min_index == -1:
        return []

    return [min_even_value, min_index]

