def get_row(lst, x):
    result = []

    for i in range(len(lst)):
        for j in range(len(lst[i])):
            if lst[i][j] == x:
                result.append((i, j))

    # Sort by row ascending, then by column descending within each row
    result.sort(key=lambda coord: (coord[0], -coord[1]))

    return result

