initial_code:
def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            # Determine if the character is uppercase or lowercase
            base = ord('A') if char.isupper() else ord('a')
            # Shift by 4 positions (2 * 2)
            shifted = (ord(char) - base + 4) % 26
            result.append(chr(base + shifted))
        else:
            result.append(char)
    return ''.join(result)

