initial_code:
def encode(message):
    vowels = 'aeiouAEIOU'
    result = []

    for char in message:
        if char.isalpha():
            # Swap case
            swapped_char = char.lower() if char.isupper() else char.upper()

            # Replace vowels with letter 2 places ahead
            if swapped_char in vowels:
                ascii_val = ord(swapped_char)
                shifted_val = ascii_val + 2
                # Handle wrap-around for 'y' and 'Y'
                if swapped_char.islower() and shifted_val > ord('z'):
                    shifted_val = ord('a') + (shifted_val - ord('z') - 1)
                elif swapped_char.isupper() and shifted_val > ord('Z'):
                    shifted_val = ord('A') + (shifted_val - ord('Z') - 1)
                swapped_char = chr(shifted_val)

            result.append(swapped_char)
        else:
            result.append(char)

    return ''.join(result)

