    for num in x:
        has_even_digit = False
        temp = num
        while temp > 0:
            digit = temp % 10
            if digit % 2 == 0:
                has_even_digit = True
                break
            temp //= 10
        if not has_even_digit:
            result.append(num)
    return sorted(result)

