initial_code:
def count_nums(arr):
    count = 0
    for num in arr:
        digit_sum = 0
        if num < 0:
            # For negative numbers, the first digit is negative
            num_str = str(abs(num))
            digit_sum += -int(num_str[0])
            for i in range(1, len(num_str)):
                digit_sum += int(num_str[i])
        else:
            # For positive numbers, all digits are positive
            for digit in str(num):
                digit_sum += int(digit)

        if digit_sum > 0:
            count += 1

    return count

