initial_code:
def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    # Try all possible right shifts (0 to n-1)
    for shift in range(n):
        # Create the array after 'shift' right shifts
        shifted_arr = arr[-shift:] + arr[:-shift] if shift > 0 else arr

        # Check if the shifted array is sorted in non-decreasing order
        is_sorted = all(shifted_arr[i] <= shifted_arr[i + 1] for i in range(n - 1))

        if is_sorted:
            return True

    return False

