initial_code:
def valid_date(date):
    # Check if the date string is not empty
    if not date:
        return False

    # Check if the format is mm-dd-yyyy
    parts = date.split('-')
    if len(parts) != 3:
        return False

    month_str, day_str, year_str = parts

    # Check if all parts are digits
    if not (month_str.isdigit() and day_str.isdigit() and year_str.isdigit()):
        return False

    # Check if month is between 1 and 12
    month = int(month_str)
    if month < 1 or month > 12:
        return False

    # Check if day is valid for the given month
    day = int(day_str)
    if day < 1:
        return False

    # Check day limits based on month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day > 30:
            return False
    elif month == 2:
        if day > 29:
            return False

    # Check if the date has leading zeros in month and day (optional, but format suggests it)
    if len(month_str) != 2 or len(day_str) != 2:
        return False

    # Check if year is valid (positive integer)
    if len(year_str) != 4:
        return False

    return True

