def is_sorted(lst):
    if len(lst) <= 1:
        return True

    # Check if sorted in ascending order
    for i in range(1, len(lst)):
        if lst[i] < lst[i-1]:
            return False

    # Check for more than 1 duplicate of the same number
    count = {}
    for num in lst:
        if num in count:
            count[num] += 1
            if count[num] > 2:
                return False
        else:
            count[num] = 1

    return True

