def tri(n):
    if n < 0:
        return []

    memo = {}

    def tribonacci(num):
        if num in memo:
            return memo[num]

        if num == 1:
            return 3
        elif num == 0:
            return 1
        elif num % 2 == 0:  # num is even
            result = 1 + num / 2
            memo[num] = result
            return result
        else:  # num is odd
            # tri(num) = tri(num-1) + tri(num-2) + tri(num+1)
            # We need tri(num+1), which may not be computed yet
            result = tribonacci(num-1) + tribonacci(num-2) + tribonacci(num+1)
            memo[num] = result
            return result

    # Compute the sequence from 0 to n
    result = []
    for i in range(n + 1):
        result.append(tribonacci(i))

    return result

