initial_code:
def is_nested(string):
    stack = []
    max_depth = 0

    for char in string:
        if char == '[':
            stack.append(char)
            max_depth = max(max_depth, len(stack))
        elif char == ']':
            if stack:
                stack.pop()
            else:
                # Unmatched closing bracket
                return False

    # Check if all brackets are matched and if there was nesting (depth > 1)
    return len(stack) == 0 and max_depth > 1

