def check_if_last_char_is_a_letter(txt):
    if not txt:
        return False

    # Check if the last character is a letter
    if not txt[-1].isalpha():
        return False

    # Check if the last character is not part of a word
    # This means the last character should be preceded by a space
    # or be the only character in the string
    if len(txt) == 1:
        return True

    return txt[-2] == ' '

