initial_code:
def file_name_check(file_name):
    # Check if there is exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Split the file name into name and extension
    name, extension = file_name.split('.')

    # Check if the name part is empty
    if not name:
        return 'No'

    # Check if the name starts with a letter from the latin alphabet
    if not name[0].isalpha():
        return 'No'

    # Check if the extension is one of the allowed types
    if extension not in ['txt', 'exe', 'dll']:
        return 'No'

    # Count the number of digits in the file name
    digit_count = sum(1 for c in file_name if c.isdigit())
    if digit_count > 3:
        return 'No'

    return 'Yes'

