def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    result_words = []

    for word in words:
        if is_prime(len(word)):
            result_words.append(word)

    return ' '.join(result_words)

