def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    # Create list of (index, number, digit_sum) to maintain original order for ties
    indexed_nums = [(i, num, digit_sum(num)) for i, num in enumerate(nums)]

    # Sort by digit sum first, then by original index for ties
    indexed_nums.sort(key=lambda x: (x[2], x[0]))

    # Extract the numbers in the new order
    return [item[1] for item in indexed_nums]

