def get_max_triples(n):
    # Create array a where a[i] = i*i - i + 1 for i from 1 to n
    a = [i * i - i + 1 for i in range(1, n + 1)]

    count = 0
    # Check all possible triples (i, j, k) where i < j < k
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1

    return count

