initial_code:
def cycpattern_check(a: str, b: str) -> bool:
    if len(b) > len(a):
        return False

    # Check if b is a substring of a
    if b in a:
        return True

    # Check all rotations of b
    for i in range(1, len(b)):
        rotated = b[i:] + b[:i]
        if rotated in a:
            return True

    return False

